mapper.select:
SELECT CASE WHEN qs.disabled THEN 'disabled' ELSE 'enable' END as tabFlag, CASE WHEN qs.disabled THEN '禁用' ELSE '启用' END as tabFlagName, COUNT(qs.id) as count FROM qc_standard qs WHERE qs.is_deleted = false
${params.permissionSql}
GROUP BY qs.disabled

SELECT qs.* FROM qc_standard qs WHERE ${params.sqlMap.default} and qs.is_deleted = false
${params.permissionSql}
ORDER BY qs.create_time DESC

SELECT qs.*, qsd.inspect_item_name as inspectItemName, qsd.inspect_requirement as inspectRequirement FROM qc_standard qs LEFT JOIN qc_standard_detail qsd ON qs.id = qsd.main_id and qsd.is_deleted = false WHERE ${params.sqlMap.default} and qs.is_deleted = false
${params.permissionSql}
ORDER BY qs.create_time DESC , qsd.sort
